    if (cached) return res.json({ language: cached, cached: true });

    const language = franc(normalized);
    await redis.set(`lang:${key}`, language, { EX: 3600 });

    res.json({ language, cached: false });
  } catch (err) {
    // Cache failures should not prevent detection.
    res.status(500).json({ error: 'language detection failed' });
  }
});
```

