Keep the game loop limited to recording a small event and enqueueing it. In Node.js, KafkaJS sends asynchronously, so you usually don’t need a worker thread—just make sure the loop never `await`s Kafka or performs synchronous disk/network I/O.

```js
const { Kafka } = require('kafkajs');

const kafka = new Kafka({ brokers: ['localhost:9092'] });
const producer = kafka.producer();

const queue = [];
const MAX_QUEUE = 10_000;
const BATCH_SIZE = 500;
let sending = false;

function logGameEvent(event) {
  // Keep this operation small and bounded.
  if (queue.length >= MAX_QUEUE) {
    // Choose this policy deliberately. For critical events, use a durable
    // local spool/outbox rather than silently dropping them.
    console.warn('Event queue full; event not queued');
    return false;
  }

  queue.push({
    key: event.playerId,
    value: JSON.stringify({
      ...event,
      timestamp: Date.now(),
    }),
  });

  return true;
}

async function flushBatch() {
  if (sending || queue.length === 0) return;
  sending = true;

  const batch = queue.splice(0, BATCH_SIZE);

  try {
    await producer.send({
      topic: 'game_events',
      messages: batch,
    });
  } catch (err) {
    // Put failed events back at the front, subject to your queue limit.
    queue.unshift(...batch);
    console.error('Kafka send failed:', err);
  } finally {
    sending = false;
  }
}

async function startLogging() {
  await producer.connect();
  setInterval(() => void flushBatch(), 50);
}

// In the game loop: enqueue only; do not await Kafka.
function onGameEvent(event) {
  logGameEvent(event);
}
```

A few important practices:

- **Bound the queue.** An unbounded queue can eventually consume all available memory if Kafka falls behind.
- **Define what happens when it fills.** Dropping or sampling may be fine for telemetry; anti-cheat, payment, or other critical events generally need a durable outbox/spool and retry strategy.
- **Batch sends** and keep only one send in flight, as above. Add retry backoff and monitoring for queue depth, send failures, and oldest-event age.
- **Handle shutdown:** stop accepting events, flush the queue with a timeout, then disconnect the producer.
- Keep event payloads compact, and avoid expensive work such as large object serialization in the tick. If that becomes measurable, prepare a lightweight event record and serialize it in the logging path.

The key is that the game loop should enqueue and move on; logging throughput and failure handling belong outside the loop.

