    "Content-Type": "application/json",
  },
});

async function translateWithRetry(text, targetLang, maxRetries = 3) {
  for (let attempt = 0; ; attempt++) {
    try {
      const { data } = await deepl.post("/translate", {
        text: [text],
        target_lang: targetLang,
