    typeof text !== 'string' ||
    !text.trim() ||
    text.length > 20_000 ||
    typeof targetLang !== 'string'
  ) {
    return res.status(400).json({ error: 'Valid text and targetLang are required.' });
  }

  const key = makeCacheKey({ text, sourceLang, targetLang });

  try {
    try {
      const cached = await redis.get(key);
      if (cached !== null) {
        return res.json({ translatedText: cached, cache: 'hit' });
      }
    } catch (err) {
      console.warn('Redis read failed; continuing without cache:', err.message);
    }

    const body = new URLSearchParams();
    body.append('text', text);
    body.append('target_lang', targetLang);
    if (sourceLang) body.append('source_lang', sourceLang);

    const response = await axios.post(
      'https://api.deepl.com/v2/translate',
      body,
      {
        headers: {
          Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        timeout: 2500,
      }
    );

    const translatedText = response.data?.translations?.[0]?.text;
    if (typeof translatedText !== 'string') {
      throw new Error('Translation provider returned an unexpected response.');
    }

    try {
      await redis.set(key, translatedText, { EX: 1200 }); // 20-minute TTL; tune to your freshness needs
    } catch (err) {
      console.warn('Redis write failed:', err.message);
    }

    return res.json({ translatedText, cache: 'miss' });
  } catch (err) {
    next(err);
  }
});

// Centralized error handler
app.use((err, req, res, next) => {
  const status = err.response?.status;
  console.error('Translation request failed:', { status, message: err.message });

  // Keep provider details and credentials out of client responses.
