const express = require("express");
const crypto = require("node:crypto");
const deepl = require("deepl");
const { createClient } = require("redis");

const app = express();
app.use(express.json({ limit: "32kb" }));

const translator = new deepl.Translator(process.env.DEEPL_AUTH_KEY);

const redis = createClient({ url: process.env.REDIS_URL });
redis.on("error", (err) => console.error("Redis error:", err));
redis.connect().catch((err) => console.error("Redis connection error:", err));

function cacheKey(text, targetLang) {
  // Hashing avoids putting full text in Redis keys.
  const hash = crypto.createHash("sha256").update(text).digest("hex");
  return `translation:${targetLang}:${hash}`;
}

app.post("/translate", async (req, res) => {
  const { texts, targetLang } = req.body;

  if (
    !Array.isArray(texts) ||
    texts.length === 0 ||
    texts.length > 50 ||
    !texts.every((text) => typeof text === "string") ||
    typeof targetLang !== "string"
  ) {
    return res.status(400).json({
      error: "Provide 1–50 texts and a targetLang.",
    });
  }

  const keys = texts.map((text) => cacheKey(text, targetLang));
  const results = new Array(texts.length);
  const missingIndexes = [];

  // If Redis is unavailable, continue to DeepL rather than failing the request.
  try {
    const cached = await Promise.all(keys.map((key) => redis.get(key)));

    cached.forEach((value, index) => {
      if (value !== null) results[index] = value;
      else missingIndexes.push(index);
    });

    const hits = cached.filter((value) => value !== null).length;
    console.info("translation_cache", {
      hits,
      misses: texts.length - hits,
      hitRate: hits / texts.length,
    });
  } catch (err) {
    console.warn("Redis read failed; translating without cache:", err.message);
    missingIndexes.push(...texts.map((_, index) => index));
  }

  if (missingIndexes.length > 0) {
    const missingTexts = missingIndexes.map((index) => texts[index]);

    try {
      const translated = await translator.translateText(
        missingTexts,
        null, // Let DeepL detect the source language.
        targetLang
      );

      const translatedTexts = Array.isArray(translated)
        ? translated.map((item) => item.text)
        : [translated.text];

      await Promise.all(
        missingIndexes.map(async (index, i) => {
          results[index] = translatedTexts[i];

          try {
            await redis.set(keys[index], translatedTexts[i], { EX: 900 });
          } catch (err) {
            console.warn("Redis write failed:", err.message);
          }
        })
      );
    } catch (err) {
      console.error("DeepL translation failed:", err);

      // Keep the app usable if the provider is unavailable.
      for (const index of missingIndexes) {
        results[index] = texts[index];
      }
    }
  }

  return res.json({ translations: results });
});

app.listen(4500, () => console.log("Translation service listening on 4500"));
```

