  },
});

function cacheKey(text, targetLang) {
  const hash = crypto.createHash("sha256").update(text).digest("hex");
  return `translation:${targetLang}:${hash}`;
}

async function translateMany(texts, targetLang, redis) {
  const results = new Array(texts.length);
  const missing = [];

  for (let i = 0; i < texts.length; i++) {
    const key = cacheKey(texts[i], targetLang);

    try {
      const cached = await redis.get(key);
      if (cached !== null) {
        results[i] = JSON.parse(cached);
        continue;
      }
    } catch (err) {
      // Cache failure should not prevent translation.
      console.warn("Redis read failed; continuing without cache:", err.message);
    }

    missing.push({ index: i, text: texts[i], key });
  }

  if (missing.length > 0) {
    const response = await deepl.post("translate", {
      text: missing.map(item => item.text),
      target_lang: targetLang,
    });

    for (let i = 0; i < missing.length; i++) {
      const translated = response.data.translations[i].text;
      const { index, key } = missing[i];
      results[index] = translated;

      try {
        await redis.set(key, JSON.stringify(translated), { EX: 900 });
      } catch (err) {
        console.warn("Redis write failed:", err.message);
      }
    }
  }

  return results;
}
```

